[
  {
    "num": 1,
    "type": "choice",
    "question": "(2025·八省联考晋陕宁青卷·★★)下列各组离子在水溶液中可以大量共存的是( )",
    "options": {
      "A": "S2O3^2-、H+、I-、Na+",
      "B": "Cl-、CO3^2-、ClO-、K+",
      "C": "NH4+、Br-、Cu2+、Ag+",
      "D": "K+、Fe3+、[Cu(NH3)4]^2+、SO4^2-"
    }
  },
  {
    "num": 2,
    "type": "choice",
    "question": "(2024·浙江卷·★★)下列离子组在溶液中能大量共存的是( )",
    "options": {
      "A": "H+、I-、Ba2+、NO3-",
      "B": "Fe3+、K+、CN-、Cl-",
      "C": "Na+、SiO3^2-、Br-、Ca2+",
      "D": "NH4+、SO4^2-、CH3COO-、HCO3-"
    }
  },
  {
    "num": 3,
    "type": "choice",
    "question": "(2025·吉林期末·★★)下列各组离子或分子能大量共存且当加入相应试剂后发生反应的离子方程式书写正确并完整的是( )",
    "options": {
      "A": "K+、Mg2+、SO4^2-；加入Ba(OH)2溶液；Ba2+ + SO4^2- == BaSO4↓",
      "B": "Na+、HCO3-、Cl-；加入NaOH溶液；OH- + HCO3- == CO3^2- + H2O",
      "C": "K+、NH3·H2O、Cl-；通入少量CO2；2OH- + CO2 == CO3^2- + H2O",
      "D": "Ca2+、NO3-、CO3^2-；加入NaHSO4溶液；CO3^2- + 2H+ == CO2↑ + H2O"
    }
  },
  {
    "num": 4,
    "type": "choice",
    "question": "(2025·黑龙江齐齐哈尔二模·★★)常温下，下列各组离子在指定溶液中一定能大量共存的是( )",
    "options": {
      "A": "硫酸四氨合铜溶液：H+、Fe3+、NO3-、Cl-",
      "B": "碱性高锰酸钾溶液：Na+、SO4^2-、CH3COO-、F-",
      "C": "FeCl3溶液：K+、NH4+、I-、SCN-",
      "D": "Na[Al(OH)4]溶液：NH4+、Ba2+、HCO3-、I-"
    }
  },
  {
    "num": 5,
    "type": "choice",
    "question": "(2025·安徽一模·★★)下列各组离子在给定溶液中一定能大量共存的是( )",
    "options": {
      "A": "C2H5OH的水溶液中：K+、MnO4-、H+、SO4^2-",
      "B": "0.1 mol·L-1 CH3COOH水溶液中：SO4^2-、NH4+、Br-、H+",
      "C": "能使甲基橙变黄的水溶液中：Mg2+、K+、ClO4-、NO3-",
      "D": "澄清透明的水溶液中：Na+、Al3+、S2-、Cl-"
    }
  },
  {
    "num": 6,
    "type": "choice",
    "question": "(2022·天津卷改编·★★)25℃时，下列各组离子中可以在水溶液中能大量共存的是( )",
    "options": {
      "A": "H+、NH4+、ClO-、Cl-",
      "B": "H+、Mg2+、I-、Fe3+",
      "C": "Na+、Al3+、HCO3-、SO4^2-",
      "D": "Na+、K+、SO3^2-、OH-"
    }
  },
  {
    "num": 7,
    "type": "choice",
    "question": "(2022·重庆卷·★★)下列操作中，不会影响溶液中K+、Al3+、Fe3+、Ba2+、Cl-、NO3-等离子大量共存的是( )",
    "options": {
      "A": "加入ZnSO4",
      "B": "加入Fe粉",
      "C": "通入NH3",
      "D": "通入CO2"
    }
  }
]
